const {
  getPackageList,
  resetPromoDetails
} = packageList
const {
  getPartnerDetails,
  removeProduct,
  getProductList,
  getPartnerConfig,
  getDefaultConfig,
  deactivatePartnerUser,
  reinstatePartnerUser,
  resetState,
  getTimezoneData,
  getWhitelabelData,
  getDomainData,
  updateBaseUrl,
  getWhitelableDefaultConfig,
  resetPartnerData,
  getPartnerProductTemplateDataRequest,
  enableDisablePackageAction,
  getApiSpecRequest,
  getPartnerClientList,
  getAllPartnerClientList,
  attachPartnerClient,
  detachPartnerClient
} = partnerAction
const { getListGroups } = partnerGroupAction
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions
class PartnerDetails extends Component {
  constructor (props) {
    super(props)
    this.state = {
      detailsData: {},
      addPartnerconfigPopupVisible: false,
      editPartnerconfigPopupVisible: false,
      addUserPanelconfigPopupVisible: false,
      editUserPanelconfigPopupVisible: false,
      whitelabelEditModalVisible: false,
      error: false,
      info: {},
      products: [],
      users: [],
      removePartnerProductStatus: '',
      productRemove: '',
      isAddNewProductVisible: false,
      isAddNewUserVisible: false,
      partnerId: '',
      partnerCode: '',
      statusAttachMessage: '',
      statusAttachUserMessage: '',
      loaderRemoveProduct: false,
      loaderAddUser: false,
      loaderAddProduct: false,
      messageAddNewUser: '',
      loaderInvokeOrReinstate: false,
      revokeMessage: '',
      reinstateMessage: '',
      partnerProducts: [],
      partnerConfig: [],
      defaultConfig: [],
      userPanelConfig: [],
      missingPartnerConfigModal: false,
      domainConfig: [],
      defaultDomainConfig: [],
      product: '',
      url: '',
      reloadPage: false,
      showEditUserModal: false,
      editUserData: undefined,
      openTemplateModal: false,
      notificationTemplateProductSelected: '',
      packageLists: [],
      partnerProductTemplate: [],
      partnerClientList: [],
      allPartnerClientList: [],
      partnerClientModalState: false
    }
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      addWhiteLabelConfigMessage,
      packageLists,
      packageListsMessage,
      getPartnerProductTemplate,
      partnerConfigStatusMessage,
      partnerConfig,
      removeProductMessage,
      products,
      partnerClientList,
      allPartnerClientList,
      partnerClientMessage,
      attachClientMessage,
      detachClientMessage
    } = nextProps

    const {
      partnerDetailData,
      partnerDetailStatus,
      messageAddNewUser,
      messageAttachProduct,
      revokeMessage,
      reinstateMessage,
      defaultConfig,
      partnerDomainConfig,
      partnerDomainConfigMessage,
      domainConfigMessage,
      domainConfig,
      defaultDomainConfig,
      defaultDomainConfigMessage,
      updatepartnerDomainConfigMessage,
      enableDisbaleProductMessage,
      generateApiSpecDataMessage,
      generateApiSpecData,
      getPartnerProductTemplateMessage
    } = nextProps.partnerData

    const { partnerCode: partner } = this.state
    // const { getRevenueShareMetaStatus } = nextProps.Recon
    if (packageListsMessage === 'success') {
      this.setState({ packageLists })
      this.props.resetPromoDetails(['packageListsMessage'])
    }
    // if (packageListsMessage !== 'success' && packageListsMessage === undefined) {
    //   this.setState({ packageLists : [] })
    // }
    if (defaultDomainConfigMessage === 'success') {
      this.setState({
        defaultDomainConfig
      })
      this.props.resetPartnerData(['defaultDomainConfigMessage'])
    }
    if (updatepartnerDomainConfigMessage === 'success') {
      notification.success({
        message: 'Successfull',
        description: 'Updated User Config'
      })
      this.props.resetPartnerData(['updatepartnerDomainConfigMessage'])
      this.props.getWhitelabelData({ params: { partner } })
      this.props.resetLoadingRedux(['GET_PARTNER_DOMAIN'])
      this.props.resetErrorRedux(['GET_PARTNER_DOMAIN'])
    }
    if (updatepartnerDomainConfigMessage && updatepartnerDomainConfigMessage !== 'success') {
      notification.error({
        message: 'Error',
        description: 'Error in Updating User Config'
      })
      this.props.resetPartnerData(['updatepartnerDomainConfigMessage'])
      this.props.getWhitelabelData({ params: { partner } })
      this.props.resetLoadingRedux(['GET_PARTNER_DOMAIN'])
      this.props.resetErrorRedux(['GET_PARTNER_DOMAIN'])
    }

    if (partnerDomainConfigMessage === 'success' && partnerDomainConfigMessage !== '') {
      this.setState({ userPanelConfig: partnerDomainConfig })
      this.props.resetPartnerData(['partnerDomainConfigMessage'])
    }
    if (partnerDomainConfigMessage !== 'success' && partnerDomainConfigMessage !== '') {
      notification.error({
        message: 'Error',
        description: 'Error in Loading User Panel Config'
      })
      this.props.resetPartnerData(['partnerDomainConfigMessage'])
    }
    // if (getRevenueShareMetaStatus !== '') {
    //   this.setState({ getRevenueShareMetaStatus, reconData: nextProps.Recon.data })
    // }
    if (reinstateMessage === 'success' || (reinstateMessage && reinstateMessage !== 'success')) {
      this.setState({ reinstateMessage, loaderInvokeOrReinstate: false })
      this.props.resetPartnerData(['reinstateMessage'])
    }
    if (revokeMessage === 'success' || (revokeMessage && revokeMessage !== 'success')) {
      this.setState({ revokeMessage, loaderInvokeOrReinstate: false })
      this.props.resetPartnerData(['revokeMessage'])
    }
    if (messageAddNewUser === 'success' || (messageAddNewUser && messageAddNewUser !== 'success')) {
      this.setState({ messageAddNewUser, loaderAddUser: false })
      this.props.resetPartnerData(['messageAddNewUser'])
    }
    if (messageAttachProduct === 'success' || (messageAttachProduct && messageAttachProduct !== 'success')) {
      this.setState({ loaderAddProduct: false })
      this.props.resetPartnerData(['messageAttachProduct'])
    }
    // if (nextProps.removePartnerProductStatus !== '') {
    //   this.setState({ removePartnerProductStatus: nextProps.removePartnerProductStatus, loaderRemoveProduct: false })
    // }
    if (partnerDetailData && partnerDetailStatus === 'success') {
      this.setState({
        info: partnerDetailData,
        products: get(partnerDetailData, 'products', []),
        users: partnerDetailData.users,
        partnerProducts: products,
        defaultConfig: defaultConfig
      })
      this.props.resetPartnerData(['partnerDetailStatus'])
    }

    if (partnerDetailStatus && partnerDetailStatus !== 'success') {
      this.setState({ error: true })
      this.props.resetPartnerData(['partnerDetailStatus'])
    }

    if (addWhiteLabelConfigMessage === 'success' && addWhiteLabelConfigMessage !== '') {
      notification.success({
        message: 'Success',
        description: 'Successfully Added Whitelable Config'
      })
      this.props.resetPartnerData(['addpartnerDomainConfigMessage'])
      this.props.getWhitelabelData({ params: { partner } })
      this.props.resetLoadingRedux(['ADD_WHITELABLE_CONFIG'])
      this.props.resetErrorRedux(['ADD_WHITELABLE_CONFIG'])
      this.adduserPanelconfigClose()
    }

    if ((addWhiteLabelConfigMessage !== 'success' && addWhiteLabelConfigMessage !== '')) {
      notification.error({
        message: 'Failed Adding Whitelable Config',
        description: 'No default path config is available, create a config with an empty product before proceeding'
      })
      this.props.resetPartnerData(['addpartnerDomainConfigMessage'])
    }

    if (domainConfigMessage === 'success') {
      this.setState({ domainConfig })
      this.props.resetPartnerData(['domainConfigMessage'])
    }

    if (enableDisbaleProductMessage === 'success') {
      const { params } = this.props.location.state
      const partner = params.partnerCode
      this.props.getPartnerProductTemplateDataRequest({ query: { partner } })
      this.props.resetPartnerData(['enableDisbaleProductMessage'])
      this.props.resetErrorRedux(['ADD_ENABLE_DISABLE_PACKAGE', 'REMOVE_PARTNER_PRODUCT'])
    }
    if (removeProductMessage === 'success') {
      const { params } = this.props.location.state
      const partner = params.partnerCode
      this.props.getPartnerProductTemplateDataRequest({ query: { partner } })
      this.props.resetPartnerData(['removePartnerProductStatus'])
      this.props.resetErrorRedux(['ADD_ENABLE_DISABLE_PACKAGE', 'REMOVE_PARTNER_PRODUCT'])
    }
    if (generateApiSpecDataMessage === 'success') {
      this.props.history.push({
        pathname: '/partner/test-create-policy/success',

        state: {
          ...generateApiSpecData
        }
      })
      this.props.resetPartnerData(['generateApiSpecDataMessage'])
    }
    if (generateApiSpecDataMessage && generateApiSpecDataMessage !== 'success') {
      notification.error({
        message: get(generateApiSpecDataMessage, 'data.message')
      })
      this.props.resetPartnerData(['generateApiSpecDataMessage'])
    }
    if (getPartnerProductTemplateMessage === 'success') {
      this.setState({
        partnerProductTemplate: get(getPartnerProductTemplate, 'product_packages', [])
      })
      this.props.resetPartnerData(['getPartnerProductTemplateMessage'])
    }
    if (getPartnerProductTemplateMessage && getPartnerProductTemplateMessage !== 'success') {
      notification.error({
        message: get(getPartnerProductTemplateMessage, 'data.message')
      })
      this.props.resetPartnerData(['getPartnerProductTemplateMessage'])
    }
    if (partnerConfigStatusMessage === 'success') {
      this.setState({
        partnerConfig
      })
      this.props.resetPartnerData(['partnerConfigStatus'])
    }
    if (partnerConfigStatusMessage && partnerConfigStatusMessage !== 'success') {
      // notification.error({
      //   message: get(partnerConfigStatusMessage, 'data.message')
      // })
      this.props.resetPartnerData(['partnerConfigStatus'])
    }
    if (partnerClientMessage === 'success') {
      this.setState({ partnerClientList, allPartnerClientList })
    }

    if (attachClientMessage !== '') {
      if (attachClientMessage === 'success') {
        notification.success({
          message: 'Success'
        })
        this.setState({ partnerClientModalState: false })
        this.props.getPartnerClientList({ query: { partner } })
        this.props.resetPartnerData(['attachClientMessage'])
      } else {
        notification.error({
          message: attachClientMessage || 'Error'
        })
        this.props.resetPartnerData(['attachClientMessage'])
      }
    }

    if (detachClientMessage !== '') {
      if (detachClientMessage === 'success') {
        notification.success({
          message: 'Success'
        })
        this.setState({ partnerClientModalState: false })
        this.props.getPartnerClientList({ query: { partner } })
        this.props.resetPartnerData(['detachClientMessage'])
      } else {
        notification.error({
          message: detachClientMessage || 'Error'
        })
        this.props.resetPartnerData(['detachClientMessage'])
      }
    }
  }

  componentDidMount () {
    if (this.props.location.state !== undefined) {
      const { params } = this.props.location.state
      const partner = params.partnerCode
      this.props.getProductList(params.partnerId)
      this.props.getPartnerConfig(partner)
      this.props.getWhitelabelData({ params: { partner } })
      this.props.getDefaultConfig(partner)
      this.props.getWhitelableDefaultConfig()
      this.props.getPartnerProductTemplateDataRequest({ query: { partner } })
      this.props.getPartnerDetails(params.partnerId)
      this.props.getPartnerClientList({ query: { partner } })
      this.props.getAllPartnerClientList()
      // this.props.getRevenueShareMeta({ partner_id: partner })
      this.setState({ partnerId: params.partnerId, partnerCode: partner })
    }
  }

  // componentWillUnmount () {
  //   this.resetState()
  // }

  handleOnBackGocarData = () => {
    const { history } = this.props
    this.props.resetState()
    history.push('/partner')
  }

  removeProductTrigger = product => {
    this.setState({ loaderRemoveProduct: true })
    const { partnerId } = this.state
    this.props.removeProduct({ product, partnerId })
  }

  productConfigLink = (data) => {
    const queryString = QuerySearchBuilder({ product_code: data })

    this.props.history.push({
      pathname: '/product-config/detail',
      search: queryString
    })
  }

  generateApiSpec = (product) => {
    const { info } = this.state
    this.props.getApiSpecRequest({
      query: {
        product_code: product,
        partner_code: get(info, 'code')
      }
    })
  }

  renderProducts = () => {
    const { info } = this.state
    const { partnerProductTemplate } = this.state
    const { permissions } = this.props
    if (partnerProductTemplate.length === 0) {
      return (
        <Col
          xs={4}
          md={6}
          lg={6}
          style={{
            padding: '10px',
            display: 'flex',
            justifyContent: 'center'
          }}
        >
          <strong>
            <h3 style={{
              color: '#5e5e5e'
            }}
            >No product found!
            </h3>
          </strong>
        </Col>
      )
    }
    return partnerProductTemplate.map((val, index) => {
      const type = get(val, 'creation_mode', 'manual')
      return (
        <Col
          span={6}
          className='product-cards'
          key={index + 1}
        >
          <CardWrapperComponent
            className='card-wrapper'
            type='inner'
            title={type}
            id={get(val, 'product_id')}
            item={val}
            history={this.props.history}
            partner={get(info, 'code')}
            goToLink={this.productConfigLink}
            permissions={permissions}
            generateApiSpecHandler={this.generateApiSpec}
            submitHandler={this.enableDisablePackage}
            delteHandler={this.deleteEnableDisablePackage}
            modalLoader={this.props.enableDisableProductLoader || this.props.removeProductLoader}
            isModalError={this.props.enableDisableProductError || this.props.removeProductError}
            modalMessage={this.props.enableDisbaleProductMessage || this.props.removeProductMessage}
            resetError={this.props.resetErrorRedux}
          />
        </Col>
      )
    })
  }

  // openAddNewProduct = () => {
  //   const { params } = this.props.location.state
  //   this.setState({ isAddNewProductVisible: true })
  //   this.props.getProductList(params.partnerId)
  // }

  onCloseModal = () => {
    this.setState({ isAddNewProductVisible: false })
  }

  handleOnCloseModalUser = () => {
    this.setState({ isAddNewUserVisible: false, showEditUserModal: false, editUserData: undefined })
  }

  statusAttachProduct = message => {
    this.setState({ statusAttachMessage: message })
  }

  onDeactivate = payload => {
    const { partnerCode, partnerId } = this.state
    this.setState({ loaderInvokeOrReinstate: true })
    this.props.deactivatePartnerUser({ payload, partnerCode, partnerId })
  }

  onActivate = payload => {
    const { partnerCode, partnerId } = this.state
    this.setState({ loaderInvokeOrReinstate: true })
    this.props.reinstatePartnerUser({ payload, partnerCode, partnerId })
  }

  handleAddNewUser = () => {
    const { partnerConfig } = this.props
    if (partnerConfig.length < 1) {
      this.setState({ missingPartnerConfigModal: true })
      return
    }
    this.setState({ isAddNewUserVisible: true })
    const { params } = this.props.location.state
    this.props.getListGroups(params.partnerId)
  }

  statusAttachUser = message => {
    this.setState({ statusAttachUserMessage: message })
  }

  handleDetectSubmit = () => {
    this.setState({ loaderAddUser: true })
  }

  triggerSubmitProduct = () => {
    this.setState({ loaderAddProduct: true })
  }
  /// /User Panel Config////

  adduserPanelconfigClose = () => {
    this.setState({
      addUserPanelconfigPopupVisible: false
    })
  }

  edituserPanelconfigClose = () => {
    this.setState({
      editUserPanelconfigPopupVisible: false
    })
  }
  /// //////////////////////

  partnerConfigClose = () => {
    this.setState({ addPartnerconfigPopupVisible: false })
  }

  editPartnerConfigClose = () => {
    this.setState({ editPartnerconfigPopupVisible: false })
  }

  userPanelConfigClose = () => {
    this.setState({})
  }

  // resetState = () => {
  //   this.props.resetState()
  // }

  handleOnAddPartnerConfig = () => {
    this.props.getTimezoneData()
    this.props.resetLoadingRedux(['POST_PARTNER_IMAGE'])
    this.props.resetErrorRedux(['POST_PARTNER_IMAGE'])
    this.setState({ addPartnerconfigPopupVisible: true })
  }

  handleOnEditPartnerConfig = () => {
    this.props.getTimezoneData()
    this.setState({ editPartnerconfigPopupVisible: true })
  }

  /// ///User PanelConfig //////
  handleOnAddUserPanelConfig = () => {
    this.setState({ addUserPanelconfigPopupVisible: true })
  }

  onEditUserPanelconfig = (id, product, url) => {
    this.setState({
      editUserPanelconfigPopupVisible: true,
      selectedconfig: id,
      product: product,
      url: url
    }, () => {
      this.props.getDomainData(id)
    })
  }

  /// ////////////////////////
  createConfig = () => {
    this.props.getTimezoneData()
    this.setState({ missingPartnerConfigModal: false, addPartnerconfigPopupVisible: true })
  }
  // detail(id) { // eslint-disable-line
  //   const { history, location } = this.props
  //   history.push({ pathname: `/recon/lists/${id}`, from: 'partner', partnerId: location.state.params.partnerId, partnerCode: location.state.params.partnerCode }) // eslint-disable-line
  // }

  edituserpanel = (id, product, url) => {
    this.onEditUserPanelconfig(id, product, url)
  }

  handleUpdateWhitelabel = () => {
    this.setState({ whitelabelEditModalVisible: true })
  }

  handleWhitelabelEditModalVisibleCancel = e => {
    this.setState({ whitelabelEditModalVisible: false })
  };

  handleEdit = (editUserData) => {
    const { params } = this.props.location.state

    this.props.getListGroups(params.partnerId)
    this.setState({ showEditUserModal: true, editUserData })
  }

  handleWhitelableChange = e => {
    const { info } = this.state
    e.preventDefault()
    this.props.form.validateFields((err, values) => {
      if (!err) {
        const data = {
          id: info.id,
          payload: {
            base_url: values.text
          }
        }
        this.props.updateBaseUrl(data)
      }
    })

    this.setState({
      whitelabelEditModalVisible: false
    })
  }

  openTemplateModal = (val) => {
    this.setState({
      openTemplateModal: !this.state.openTemplateModal,
      notificationTemplateProductSelected: val || ''
    }, () => {
      const { openTemplateModal, partnerCode } = this.state
      if (!openTemplateModal) {
        setTimeout(() => {
          this.props.getPartnerProductTemplateDataRequest({ query: { partner: partnerCode } })
        }, 3000)
      }
    })
  }

  openImageModal = (val) => {
    Modal.info({
      title: 'Notification Template Image',
      content: (
        <img src={val} style={{ width: '100%' }} alt='Notification' />
      )
      // onOk() {},
    })
  }

  selectedProductAction = (product) => {
    this.openTemplateModal(product)
  }

  enableDisablePackage = (data) => {
    const { partnerCode } = this.state
    const partnerPayload = {
      partner: partnerCode,
      data: data.packages.map(item => {
        return {
          package_id: item.id,
          create_policy: item.create_policy,
          attach_package: item.attach_package
        }
      })
    }
    this.props.enableDisablePackageAction(partnerPayload)
  }

  deleteEnableDisablePackage = (data) => {
    this.removeProductTrigger(data)
  }

  packageHandler = (data) => {
    this.props.getPackageList(data)
  }

  unsetstateFunction = () => {
    this.setState({
      packageLists: []
    })
  }

  handleAddPartnerClient = () => {
    this.setState({ partnerClientModalState: true })
  }

  handleDispatchClientBtn = (data) => {
    const { detachPartnerClient } = this.props
    const { partnerId, allPartnerClientList } = this.state
    const selectedId = allPartnerClientList.find((client) => client.code === data)
    confirm({
      title: `Dispatch ${data} from the List?`,
      okText: 'Yes',
      okType: 'danger',
      cancelText: 'No',
      onOk () {
        detachPartnerClient({
          query: {
            partner: partnerId
          },
          body: {
            client_ids: [selectedId?.id]
          }
        })
      },
      onCancel () {
      }
    })
  }

  render () {
    let config = ''
    const {
      info,
      products,
      users,
      removePartnerProductStatus,
      productRemove,
      statusAttachMessage,
      loaderAddUser,
      messageAddNewUser,
      loaderInvokeOrReinstate,
      revokeMessage,
      reinstateMessage,
      partnerProducts,
      userPanelConfig,
      domainConfig,
      selectedconfig,
      defaultDomainConfig,
      product,
      url,
      showEditUserModal,
      editUserData,
      notificationTemplateProductSelected,
      packageLists,
      partnerConfig,
      partnerClientModalState
    } = this.state

    const { getFieldDecorator } = this.props.form
    const { defaultConfig, permissions, partnerDomainLoading, getPartnerProductTemplate, partnerDomainError, getPartnerProductTemplateError, getPartnerProductTemplateLoading, generateApiSpecLoading, partnerConfigLoading, templatePartnerProductLoading, partnerClientListLoading } = this.props
    const productsData = get(getPartnerProductTemplate, 'products', [])
    const partnerData = get(getPartnerProductTemplate, 'partner', [])
    const notificationTemplateData = []
    if (products.length > 0) {
      productsData.forEach((item, i) => {
        let newObject = {}
        newObject.product = Object.keys(item)[0]
        item[Object.keys(item)[0]].forEach(objectsData => {
          newObject = { ...newObject, ...objectsData }
        })
        notificationTemplateData.push(newObject)
      })
    } else {
      let newObject = {}
      partnerData.forEach(item => {
        newObject = { ...newObject, ...item }
      })
      notificationTemplateData.push(newObject)
    }
    // TODO: Move the table columns to seperate static folder
    const columns = [
      {
        dataIndex: 'name',
        width: 150
      }, {
        dataIndex: 'value'
      }
    ]
    const value1 = [
      {
        key: '1',
        name: <strong>Name</strong>,
        value: info.name || '-'
      }, {
        key: '2',
        name: <strong>Email</strong>,
        value: info.contact_email || '-'
      }, {
        key: '3',
        name: <strong>Phone</strong>,
        value: info.contact_phone || '-'
      }, {
        key: '4',
        name: <strong>Whitelabel url</strong>,
        value: info.base_url || '-'
      }
    ]
    const value2 = [
      {
        key: '5',
        name: <strong>Code</strong>,
        value: info.code || '-'
      }, {
        key: '6',
        name: <strong>Status</strong>,
        value: info.status || '-'
      }, {
        key: '7',
        name: <strong>Created At</strong>,
        value: moment(info.created_at).format('DD MMMM YYYY') || '-'
      }
    ]
    const notificationTemplateColumn = [
      {
        title: 'Product',
        dataIndex: 'product',
        key: 'product'
      },
      {
        title: 'Header Logo',
        dataIndex: 'logo',
        key: 'logo',
        render: (value) => value && <img src={value} style={{ height: 100 }} onClick={() => this.openImageModal(value)} alt='logo' />
      },
      {
        title: 'Additional text',
        dataIndex: 'additionalText',
        key: 'additionalText',
      },
      {
        title: 'Add Benefits',
        dataIndex: 'benefits',
        key: 'benefits',
      },
      {
        title: 'Endorsement URL',
        dataIndex: 'endorsementUrl',
        key: 'endorsementUrl',
      },
      {
        title: 'Color Code',
        dataIndex: 'colorCode',
        key: 'colorCode',
      },
      {
        title: 'Theme',
        dataIndex: 'theme',
        key: 'theme',
      },
      {
        title: 'Action',
        dataIndex: 'is_active',
        key: 'action',
        render: (value, payload) => {
          const { product } = payload
          return <span onClick={() => this.selectedProductAction(product || '')}>Edit</span>
        }
      }
    ]

    const clientUser = [
      {
        title: 'Client',
        render: (data) => data
      },
      {
        title: 'Action',
        render: (data) => <Icon type='delete' theme='twoTone' className='pointer' onClick={() => this.handleDispatchClientBtn(data)} />
      }
    ]

    const columnsUser = [
      {
        title: 'Name',
        dataIndex: 'name',
        key: 'name'
      }, {
        title: 'Email',
        dataIndex: 'email',
        key: 'email'
      }, {
        title: 'Phone',
        dataIndex: 'phone',
        key: 'phone'
      }, {
        title: 'Last login',
        dataIndex: 'last_login',
        key: 'last_login'
      }, {
        title: 'Status',
        dataIndex: 'is_active',
        key: 'is_active',
        render: (value) => value ? 'Active' : 'Inactive'
      }, {
        title: 'Action',
        dataIndex: 'is_active',
        key: 'action',
        render: (value, payload) => {
          const { permissions } = this.props

          if (value) {
            if (permissions.indexOf('ops.revoke_partner_users') > -1) {
              return (
                <Row type='flex' justify='space-between' align='middle'>
                  <Icon type='edit' className='edit-user' onClick={() => this.handleEdit(payload)} />
                  <Popconfirm
                    title='Are you sure to revoke this user?' okText='YES' cancelText='NO' onConfirm={() => {
                      this.onDeactivate(payload)
                    }}
                  >
                    <span className='anchor'>Revoke</span>
                  </Popconfirm>
                </Row>
              )
            }
          } else {
            if (permissions.indexOf('ops.reinstate_partner_users') > -1) {
              return (
                <Row type='flex' justify='space-between' align='middle'>
                  <Icon type='edit' className='edit-user' onClick={() => this.handleEdit(payload)} />
                  <Popconfirm
                    title='Are you sure to reinstate this user?' okText='YES' cancelText='NO' onConfirm={() => {
                      this.onActivate(payload)
                    }}
                  >
                    <span className='anchor'>Reinstate</span>
                  </Popconfirm>
                </Row>
              )
            }
          }
        }
      }
    ]

    if (partnerConfig && partnerConfig.length > 0) {
      config = partnerConfig.map((d, index) => (
        <Col
          key={index} span={6} style={{
            padding: '10px',
            wordBreak: 'break-word'
          }}
        >
          <p>
            <b>{d.config_type.description}</b>
          </p>
          <p>{
            d.config_type.name === 'PARTNER_LOGO'
              ? <a href={d.value} target='_blank' rel='noopener noreferrer'>logo</a>
              : d.value
          }
          </p>
        </Col>))
    }
    const columnsUserconfig = [
      {
        title: 'Action',
        key: 'action',
        render: (i, data) => (
          <span>
            <span
              className='anchor' onClick={() => {
                this.edituserpanel(i.id, i.product, i.url)
              }}
            >
              Edit
            </span>
          </span>
        )
      }, {

        title: 'Url',
        dataIndex: 'url',
        key: 'url'
      }, {

        title: 'Product',
        dataIndex: 'product',
        key: 'product'
      }

    ]

    return (
      <LayoutContentWrapper>
        {
          this.state.error &&
            <AlertSection>
              <Alert className='page-error' message='Ooops, something went terribly wrong!' type='error' closeText='Close' />
            </AlertSection>
        }
        {
          (removePartnerProductStatus !== '' && removePartnerProductStatus === 'success') &&
            <AlertSection>
              <Alert className='product-remove' message={`Product ${productRemove} removed!`} type='success' closeText='Close' />
            </AlertSection>
        }
        {
          (removePartnerProductStatus !== 'success' && removePartnerProductStatus !== '') &&
            <AlertSection>
              <Alert className='failed-product-remove' message={`Failed remove product ${productRemove.productName}!`} type='error' closeText='Close' />
            </AlertSection>
        }
        {
          (statusAttachMessage !== '' && statusAttachMessage === 'success') &&
            <AlertSection>
              <Alert className='product-added' message='product has been added successfully' type='success' closeText='Close' />
            </AlertSection>
        }
        {
          (statusAttachMessage !== '' && statusAttachMessage !== 'success') &&
            <AlertSection>
              <Alert className='product-failed-add' message='Product is failed to added!' type='error' closeText='Close' />
            </AlertSection>
        }
        {
          (messageAddNewUser !== '' && messageAddNewUser === 'success') &&
            <AlertSection>
              <Alert className='user-add' message='User has been added successfully' type='success' closeText='Close' />
            </AlertSection>
        }
        {
          (messageAddNewUser !== '' && messageAddNewUser !== 'success') &&
            <AlertSection>
              <Alert className='user-add-failed' message={messageAddNewUser} type='error' closeText='Close' />
            </AlertSection>
        }
        {
          (revokeMessage !== '' && revokeMessage === 'success') &&
            <AlertSection>
              <Alert className='user-revoked' message='User revoked!' type='success' closeText='Close' />
            </AlertSection>
        }
        {
          (revokeMessage !== '' && revokeMessage !== 'success') &&
            <AlertSection>
              <Alert className='user-revoke-failed' message='User failed to revoke!' type='error' closeText='Close' />
            </AlertSection>
        }
        {
          (reinstateMessage !== '' && reinstateMessage === 'success') &&
            <AlertSection>
              <Alert className='user-reinitiate' message='User reinstated!' type='success' closeText='Close' />
            </AlertSection>
        }
        {
          (reinstateMessage !== '' && reinstateMessage !== 'success') &&
            <AlertSection>
              <Alert className='user-reinitiate-failed' message='User failed to reinstate!' type='error' closeText='Close' />
            </AlertSection>
        }
        {/* Alert Section Ends Here */}

        {/* Modal Section Starts Here */}
        <MissingPartnerConfigModal isOpen={this.state.missingPartnerConfigModal} createConfig={this.createConfig} />
        <AddPartnerConfigModal config={this.state.defaultConfig} isOpen={this.state.addPartnerconfigPopupVisible} triggerClose={this.partnerConfigClose} partner={this.state.partnerCode} defaultConfig={defaultConfig} {...this.props} />
        <Modal title='WhiteLabel Url Edit' visible={this.state.whitelabelEditModalVisible} onOk={this.handleWhitelableChange} onCancel={this.handleWhitelabelEditModalVisibleCancel}>
          <Form onSubmit={this.handleWhitelableChange}>
            <Form.Item>
              {
                getFieldDecorator('text',
                  { initialValue: info.base_url })(<Input />)
              }
            </Form.Item>
          </Form>
        </Modal>
        {/* <AddNewProductModal isOpen={this.state.isAddNewProductVisible} partnerId={partnerId} onTriggerClose={this.onCloseModal} onTriggerSubmit={this.triggerSubmitProduct} statusAttachProduct={this.statusAttachProduct} products={partnerProducts} /> */}
        <EditPartnerConfigModal isOpen={this.state.editPartnerconfigPopupVisible} triggerClose={this.editPartnerConfigClose} partner={this.state.partnerCode} config={partnerConfig} defaultConfig={defaultConfig} />
        <AddUserPannelConfig config={defaultDomainConfig} isOpen={this.state.addUserPanelconfigPopupVisible} triggerClose={this.adduserPanelconfigClose} partner={this.state.partnerCode} defaultConfig={defaultDomainConfig} />
        <EditPannelConfig config={defaultDomainConfig} isOpen={this.state.editUserPanelconfigPopupVisible} triggerClose={this.edituserPanelconfigClose} partner={this.state.partnerCode} editpartnerconfig={domainConfig} selectedConfig={selectedconfig} product={product} url={url} />
        <AddNewUserModal
          isOpen={this.state.isAddNewUserVisible || showEditUserModal}
          editUserData={editUserData}
          partnerCode={this.state.partnerCode}
          partnerId={this.state.partnerId}
          onTriggerCloseAddUser={this.handleOnCloseModalUser}
          onTriggerSubmit={this.handleDetectSubmit}
          statusAttachProduct={this.statusAttachUser}
        />
        {
          this.state.openTemplateModal &&
            <TemplateModal
              isOpen={this.state.openTemplateModal}
              partnerCode={this.state.partnerCode}
              partnerId={this.state.partnerId}
              products={products}
              selectedProduct={notificationTemplateProductSelected}
              onCloseModal={() => this.openTemplateModal('')}
            />
        }
        {
          partnerClientModalState &&
            <AddClientModal
              isOpen={partnerClientModalState}
              onCloseModal={() => this.setState({ partnerClientModalState: false })}
              clientList={this.state.allPartnerClientList}
              partnerCode={this.state.partnerId}
              attachPartnerClient={this.props.attachPartnerClient}
            />
        }
        {/* Modal Section Ends Here */}

        {/*  Partner Information Section Starts Here */}
        <LayoutContent className='partner-information'>
          <PartnerStyled>
            <Spin tip='Loading ...' spinning={!!partnerConfigLoading}>
              <Row type='flex' justify='space-around'>
                <Col span={12}>
                  <Button
                    type='primary'
                    className='back-button'
                    onClick={this.handleOnBackGocarData}
                  >
                    <Icon type='left' />Back
                  </Button>
                  <h3>Partner Information</h3>
                </Col>
                <Col span={12}>
                  <div>
                    <Button
                      className='update-whitelable-btn'
                      type='primary' onClick={this.handleUpdateWhitelabel}
                    >
                      Update WhiteLabel-url
                    </Button>
                  </div>
                  {
                    partnerConfig.length === 0 &&
                      <div>
                        <PermissionChecker permissionSetter='ops.add_partner_config' permissionGetter={permissions}>
                          <Button className='add-partner-config-btn' type='primary' onClick={this.handleOnAddPartnerConfig}>
                            Add Partner Config
                          </Button>
                        </PermissionChecker>
                      </div>
                  }
                </Col>
              </Row>
              <div className='partner-information-table'>
                <Row>
                  <Col span={12}>
                    <Table rowKey='partner-info-1' showHeader={false} columns={columns} dataSource={value1} />
                  </Col>
                  <Col span={12}>
                    <Table rowKey='partner-info-2' showHeader={false} columns={columns} dataSource={value2} />
                  </Col>
                </Row>
              </div>
            </Spin>
          </PartnerStyled>
        </LayoutContent>
        {/* Partner Information Ends Here */}

        {/* Partner Config Starts Here */}
        <LayoutContent className='partner-config-section'>
          <Spin tip='Loading ...' spinning={!!partnerConfigLoading}>
            <ProductStyled>
              <Row type='flex'>
                <Col span={12}>
                  <h3>Partner Config</h3>
                </Col>
                {
                  this.state.partnerConfig.length > 0 &&
                    <Col span={12}>
                      <PermissionChecker permissionSetter='ops.edit_partner_config' permissionGetter={permissions}>
                        <Button className='edit-partner-config-btn' type='primary' onClick={this.handleOnEditPartnerConfig}>
                          Edit Partner Config
                        </Button>
                      </PermissionChecker>
                    </Col>
                }

              </Row>
              <Row type='flex'>
                {config}
              </Row>
            </ProductStyled>
          </Spin>
        </LayoutContent>
        {/* Partner Config Ends Here */}

        {/* User Panel Config Starts Here */}
        <LayoutContent className='user-panel-config-section'>
          <ProductStyled>
            <Spin tip='Loading ...' spinning={partnerDomainLoading && !partnerDomainError}>
              <Row type='flex'>
                <Col span={12}>
                  <h3>User Panel Config</h3>
                </Col>
                <Col span={12}>
                  <Button
                    className='add-config-btn'
                    type='primary'
                    onClick={this.handleOnAddUserPanelConfig}
                  >
                    Add Config
                  </Button>
                </Col>
              </Row>
              <Row type='flex'>
                <Col span={24}>
                  <Table
                    rowKey='addConfig'
                    className='add-config-table'
                    columns={columnsUserconfig}
                    dataSource={userPanelConfig}
                  />
                </Col>
              </Row>
            </Spin>
          </ProductStyled>
        </LayoutContent>
        {/* User PAnel Config Ends Here */}

        {/* Products Section Starts Here */}
        <LayoutContent className='product-section'>
          <Spin tip='Loading ...' spinning={(!getPartnerProductTemplateError && getPartnerProductTemplateLoading) || (!!generateApiSpecLoading)}>
            <ProductStyled>
              <h3>Products</h3>
              <Row type='flex' gutter={20}>
                <Col
                  span={6}
                  className='card-column'
                >
                  {
                    permissions.indexOf('ops.add_partner_product') > -1
                      ? (
                        // <Card
                        //   type='inner'
                        //   title='Add new Product'
                        //   onClick={this.openAddNewProduct}
                        //   className='card'
                        // >
                        //   <div className='new-product-container'>
                        //     <i className='fas fa-plus fa-5x' />
                        //   </div>
                        // </Card>
                        <CardWrapperComponent
                          className='card-wrapper'
                          type='inner'
                          title='add'
                          partner={this.state.partnerCode}
                          permissions={[]}
                          payload={partnerProducts}
                          getPackages={this.packageHandler}
                          packages={packageLists}
                          submitHandler={this.enableDisablePackage}
                          unsetstateFunction={this.unsetstateFunction}
                          modalLoader={this.props.enableDisableProductLoader || this.props.removeProductLoader}
                          isModalError={this.props.enableDisableProductError || this.props.removeProductError}
                          modalMessage={this.props.enableDisbaleProductMessage || this.props.removeProductMessage}
                          resetError={this.props.resetErrorRedux}
                          successMessage={this.props.enableDisbaleProductMessage}
                        />
                        )
                      : (
                        <Card type='inner' className='card'>
                          <div className='new-product-container'>
                            <h4>You dont have permission to add product.</h4>
                          </div>
                        </Card>
                        )
                  }
                </Col>
                {this.renderProducts()}
              </Row>
            </ProductStyled>
          </Spin>
        </LayoutContent>
        {/* Products Section End Here */}
        <LayoutContent className='partner-user-section'>
          <PartnerStyled>
            <Spin tip='Loading ...' spinning={loaderAddUser || loaderInvokeOrReinstate}>
              <Row type='flex' justify='space-between'>
                <Col>
                  <h3>Partner Users</h3>
                </Col>
                {
                  (permissions.indexOf('ops.add_partner_users') > -1) && (
                    <Col>
                      <Button type='primary' icon='plus' size='large' onClick={this.handleAddNewUser}>
                        Add User
                      </Button>
                    </Col>
                  )
                }
              </Row>
              <Row type='flex' className='partner-table-section'>
                <Col span={24}>
                  <Table
                    rowKey='addUser'
                    // pagination={{ pageSize: 5 }}
                    columns={columnsUser}
                    dataSource={users}
                  />
                </Col>
              </Row>
            </Spin>
          </PartnerStyled>
        </LayoutContent>

        <LayoutContent className='client-user-section'>
          <PartnerStyled>
            <Spin tip='Loading Client List ...' spinning={!!partnerClientListLoading}>
              <Row type='flex' justify='space-between'>
                <Col>
                  <h3>Partner Clients </h3>
                </Col>
                <Col>
                  <Button type='primary' icon='plus' size='large' onClick={this.handleAddPartnerClient}>
                    Add Partner Client
                  </Button>
                </Col>
              </Row>

              <Row type='flex' className='client-table-section'>
                <Col span={24}>
                  <Table
                    rowKey='addUser'
                    pagination={false}
                    columns={clientUser}
                    dataSource={this.state.partnerClientList}
                  />
                </Col>
              </Row>
            </Spin>
          </PartnerStyled>
        </LayoutContent>

        <LayoutContent className='notification-template-builder-section'>
          <PartnerStyled>
            <Row type='flex' justify='space-between'>
              <Col>
                <h3>Notification Template Builder</h3>
              </Col>
              <Col>
                <Button type='primary' icon='plus' size='large' onClick={() => this.openTemplateModal('')}>
                  Add Template Config
                </Button>
              </Col>
            </Row>
            <Row type='flex' className='partner-table-section'>
              <Col span={24}>
                <Table
                  rowKey='addTemplateConfig'
                  pagination={{
                    pageSize: 1000
                  }}
                  columns={notificationTemplateColumn}
                  dataSource={notificationTemplateData}
                  scroll={{ x: true }}
                  loading={templatePartnerProductLoading}
                />
              </Col>
            </Row>
          </PartnerStyled>
        </LayoutContent>
      </LayoutContentWrapper>
    )
  }
}

PartnerDetails.propTypes = {
  partnerData: PropTypes.object.isRequired,
  defaultConfig: PropTypes.array.isRequired,
  partnerConfig: PropTypes.array.isRequired,
  partnerDomainLoading: PropTypes.bool,
  templatePartnerProductLoading: PropTypes.bool,
  partnerDomainError: PropTypes.bool
}

PartnerDetails.defaultProps = {
  packageLists: [],
  partnerData: {},
  defaultConfig: [],
  partnerConfig: [],
  partnerDomainLoading: false,
  partnerDomainError: false
}

const WrappedComponent = Form.create()(PartnerDetails)

export default connect(state => ({
  partnerData: state.Partner,
  defaultConfig: state.Partner.defaultConfig,
  partnerConfig: state.Partner.partnerConfig,
  partnerConfigStatusMessage: state.Partner.partnerConfigStatus,
  partnerConfigLoading: state.Loading.GET_PARTNER_CONFIG,
  editConfigLoading: state.Loading.GET_DOMAIN_CONFIG,
  editConfigError: state.Error.GET_DOMAIN_CONFIG_DATA,
  partnerDomainLoading: state.Loading.GET_PARTNER_DOMAIN,
  partnerDomainError: state.Error.GET_PARTNER_DOMAIN,
  templatePartnerProductLoading: state.Loading.GET_TEMPLATE_PARTNERPRODUCT_DATA,
  addWhiteLabelConfigMessage: state.Partner.addpartnerDomainConfigMessage,
  removePartnerProductStatus: state.Partner.removePartnerProductStatus,
  dataProfile: state.Auth.profile,
  getPartnerDetailData: state.Partner.partnerDetailData,
  getPArtnerDetailMessage: state.Partner.partnerListStatus,
  getPartnerProductTemplateMessage: state.Partner.getPartnerProductTemplateMessage,
  getPartnerProductTemplate: state.Partner.getPartnerProductTemplateData,
  getPartnerProductTemplateLoading: state.Loading.GET_TEMPLATE_PARTNERPRODUCT_DATA,
  getPartnerProductTemplateError: state.Error.GET_TEMPLATE_PARTNERPRODUCT_DATA,
  // Recon: state.Recon
  enableDisbaleProductMessage: state.Partner.enableDisbaleProductMessage,
  packageLists: state.PromoDetails.packageLists,
  packageListsMessage: state.PromoDetails.packageListsMessage,
  enableDisableProductLoader: state.Loading.ADD_ENABLE_DISABLE_PACKAGE,
  enableDisableProductError: state.Error.ADD_ENABLE_DISABLE_PACKAGE,
  removeProductLoader: state.Loading.REMOVE_PARTNER_PRODUCT,
  removeProductError: state.Error.REMOVE_PARTNER_PRODUCT,
  removeProductMessage: state.Partner.removePartnerProductStatus,
  generateApiSpecLoading: state.Loading.GENERATE_API_SPEC,
  generateApiSpecError: state.Error.GENERATE_API_SPEC,
  generateApiSpecDataMessage: state.Partner.generateApiSpecDataMessage,
  generateApiSpecData: state.Partner.generateApiSpecData,
  products: state.Partner.products,

  partnerClientList: state.Partner.partnerClientList,
  partnerClientListLoading: state.Loading.GET_PARTNER_CLIENT_LIST,
  allPartnerClientList: state.Partner.allPartnerClientList,
  partnerClientStatus: state.Partner.partnerClientStatus,
  partnerClientMessage: state.Partner.partnerClientMessage,
  attachClientMessage: state.Partner.attachClientMessage,
  detachClientMessage: state.Partner.detachClientMessage
}), {
  getDomainData,
  getPartnerDetails,
  getPartnerConfig,
  getDefaultConfig,
  removeProduct,
  getProductList,
  deactivatePartnerUser,
  getListGroups,
  reinstatePartnerUser,
  resetState,
  resetLoadingRedux,
  resetErrorRedux,
  getTimezoneData,
  getWhitelabelData,
  updateBaseUrl,
  getWhitelableDefaultConfig,
  resetPartnerData,
  getPartnerProductTemplateDataRequest,
  enableDisablePackageAction,
  getPackageList,
  resetPromoDetails,
  getApiSpecRequest,
  getPartnerClientList,
  getAllPartnerClientList,
  attachPartnerClient,
  detachPartnerClient
})(WrappedComponent)
