/* eslint-disable react-hooks/exhaustive-deps */
import React, { useState, useEffect } from 'react'
import { Row, Col, Switch, Button, Select, Icon, Popconfirm, Spin, Alert } from 'antd'
import { get, size } from 'lodash'
import { StyledModal } from './AddProductModal.style'

const { Option } = Select

export const ModalTitleHeader = ({ permissions, deleteItem, closeModal }) => {
  return (
    <Row type='flex' justify='space-between'>
      <Col>
        <b>Edit</b>
      </Col>
      {
        (permissions.indexOf('ops.remove_partner_product') > -1) &&
          <Col>
            <Row type='flex' justify='space-around' gutter={10}>
              <Col>
                <Popconfirm
                  title='Are you sure to delete this product?'
                  okText='DELETE'
                  cancelText='No'
                  onConfirm={deleteItem}
                >
                  <Icon type='delete' theme='twoTone' />
                </Popconfirm>
              </Col>
              {/* <Col>
                  <Icon type="close-square" theme="twoTone" onClick={closeModal} />
                </Col> */}
            </Row>
          </Col>
      }
    </Row>
  )
}

export default function AddProductModalComponent (
  {
    visible,
    toggleModal,
    type,
    partner,
    data,
    payload,
    submitHandler,
    delteHandler,
    permissions,
    getPackages,
    packages,
    unsetstateFunction = null,
    modalLoader,
    isModalError,
    modalMessage,
    resetError
  }
) {
  const [packageData, updatePackageData] = useState([])
  const [payloadData, updatePayloadData] = useState([])
  const [selectedProduct, updateSelectedProduct] = useState({})
  const [selectedValue, selectFieldUpdate] = useState('')

  useEffect(() => {
    if (packages.length === 0 && packageData.length > 0) {
      updatePackageData([])
    }

    // if (packages.length > 0 && packageData.length === 0) {
    if (packages.length > 0) {
      const initialData = packages.map(item => {
        return {
          id: get(item, 'id'),
          code: get(item, 'package_code', get(item, 'code')),
          create_policy: get(item, 'create_policy', false),
          attach_package: get(item, 'attach_package', false)
        }
      })
      updatePackageData(initialData)
      const makeProduct = {
        ...selectedProduct,
        packages: initialData
      }
      updateSelectedProduct(makeProduct)
      localStorage.setItem('product-package', JSON.stringify(makeProduct))
    }
  }, [JSON.stringify(packages)])

  useEffect(() => {
    return () => {
      selectFieldUpdate('')
      updatePackageData([])
      resetError(['REMOVE_PARTNER_PRODUCT', 'ADD_ENABLE_DISABLE_PACKAGE'])
      localStorage.removeItem('product-package')
    }
  }, [visible])

  useEffect(() => {
    if (size(data) > 0 && packageData.length === 0) {
      const initialData = get(data, 'packages', []).map(item => {
        return {
          ...item,
          create_policy: get(item, 'create_policy'),
          attach_package: get(item, 'attach_package')
        }
      })
      updatePackageData(initialData)
      const singleData = {
        ...data,
        packages: initialData
      }
      updateSelectedProduct(singleData)
      localStorage.setItem('product-package', JSON.stringify(singleData))
    }
    if (payload.length > 0 && payloadData.length === 0) {
      updatePayloadData(payload)
    }
  }, [data, payload])

  const handleOk = () => {
    const localData = JSON.parse(localStorage.getItem('product-package'))
    submitHandler({
      ...localData,
      packages: get(localData, 'packages', []).map((item) => {
        return {
          id: item.id,
          code: item.code,
          create_policy: item.create_policy,
          attach_package: item.attach_package
        }
      })
    })
    // toggleModal(false)
    // localStorage.removeItem('product-package')
  }

  const handleCancel = () => {
    if (typeof unsetstateFunction === 'function') {
      unsetstateFunction()
    }
    toggleModal(false)
    localStorage.removeItem('product-package')
  }

  const updateSwitchData = (e, selectedData, mode) => {
    const modifiedData = packageData.map((item) => {
      if (item.code === get(selectedData, 'code')) {
        if (mode === 'attach_package') {
          return {
            ...item,
            attach_package: e,
            create_policy: e
          }
        }
        if (mode === 'create_policy') {
          return {
            ...item,
            create_policy: e
          }
        }
      }
      return item
    })
    updatePackageData(modifiedData)
    const singleData = {
      ...selectedProduct,
      packages: modifiedData
    }
    updateSelectedProduct(singleData)
    localStorage.setItem('product-package', JSON.stringify(singleData))
  }

  const onChangeHandle = (value) => {
    selectFieldUpdate(value)
    if (payload.length > 0) {
      const selectedData = payload.find(item => item.id === value)
      const makeProduct = {
        product: get(selectedData, 'name'),
        product_id: get(selectedProduct, 'id')
      }
      updateSelectedProduct(makeProduct)
      getPackages(get(selectedData, 'name'))
    }
  }

  const deleteItemHandler = () => {
    const localData = type === 'add' ? selectedProduct : JSON.parse(localStorage.getItem('product-package'))
    delteHandler({
      ...localData,
      packages: get(localData, 'packages', []).map((item) => {
        return {
          id: item.id,
          code: item.code,
          create_policy: item.create_policy,
          attach_package: item.attach_package
        }
      })
    })
    // localStorage.removeItem('product-package')
    // toggleModal(false)
  }

  useEffect(() => {
    return () => {
      resetError(['REMOVE_PARTNER_PRODUCT', 'ADD_ENABLE_DISABLE_PACKAGE'])
      localStorage.removeItem('product-package')
    }
  }, [])

  return (
    <StyledModal
      className='add-product-modal'
      title={(type === 'manual' || type === 'config') ? (<ModalTitleHeader permissions={permissions} deleteItem={deleteItemHandler} closeModal={() => toggleModal(false)} />) : (<b>Add Product</b>)}
      visible={visible}
      footer={null}
      closable={false}
    >
      <Spin spinning={!!modalLoader}>
        {isModalError && <Alert banner message={modalMessage} type='error' />}
        <Row type='flex' justify='start' gutter={40}>
          <Col>
            <b>Product</b>
          </Col>
          {
            (type === 'manual' || type === 'config')
              ? <Col> <span>{get(data, 'product')}</span> </Col>
              : (
                <Col>
                  <Select
                    showSearch
                    value={selectedValue}
                    placeholder='Select a product'
                    optionFilterProp='children'
                    onChange={onChangeHandle}
                    className='width-300'
                  >
                    {payloadData.map((item, index) => (<Option key={index} value={item.id}>{item.name}</Option>))}
                  </Select>
                </Col>
                )
          }
        </Row>
        <Row type='flex' justify='start' gutter={40}>
          <Col>
            <b>Partner</b>
          </Col>
          <Col>
            <span>{partner}</span>
          </Col>
        </Row>
        {packageData.length > 0 &&
          (
            <Row type='flex' className='mt-30'>
              <Col span={8}>
                <b>Package Code</b>
              </Col>
              <Col span={8}>
                <b>Attach Package</b>
              </Col>
              <Col span={8}>
                <b>Create Policy</b>
              </Col>
            </Row>
          )}
        <Row type='flex'>
          <Col span={24}>
            {
              packageData.map((item, index) => {
                return (
                  <Row key={index} type='flex' gutter={80} className='p-10'>
                    <Col span={8}>
                      {item.code}
                    </Col>
                    <Col span={8}>
                      <Switch className={item.attach_package ? 'selected-switch' : 'unselected-switch'} checked={item.attach_package} onChange={(e) => updateSwitchData(e, item, 'attach_package')} />
                    </Col>
                    <Col span={8}>
                      <Switch className={item.create_policy ? 'selected-switch' : 'unselected-switch'} checked={item.create_policy} onChange={(e) => updateSwitchData(e, item, 'create_policy')} disabled={!item.attach_package} />
                    </Col>
                  </Row>
                )
              })
            }
          </Col>
        </Row>
        <Row type='flex' justify='center' gutter={10} className='mt-50'>
          <Col span={12} className='flex-center'>
            <Button
              shape='round'
              className='bg-cancel font-15'
              onClick={handleCancel}
            >
              <b>Cancel</b>
            </Button>
          </Col>
          <Col span={12} className='flex-center'>
            <Button
              shape='round'
              className='bg-save font-15'
              onClick={handleOk}
            >
              <b>{type === 'add' ? 'Submit' : 'Save'}</b>
            </Button>
          </Col>
        </Row>
      </Spin>
    </StyledModal>
  )
}
