import React, { Component } from 'react'
import {
  Form,
  Upload,
  Button,
  Icon,
  message,
  Input,
  Select,
  Modal,
  Checkbox,
  Row,
  Col
} from 'antd'
import { connect } from 'react-redux'
import notificationActions from '../../redux/notifications/actions'
import parnerActions from '../../redux/partner/actions'
// import validator from '../../../helpers/validator'
import _ from 'lodash'
import ModalWrapper from './templateForm.style'

const {
  startUploadTemplate
} = notificationActions
const {
  addNotificationTemplatePartnerRequest,
  addNotificationTemplateProductRequest
} = parnerActions
const dummyRequest = ({ file, onSuccess }) => {
  setTimeout(() => {
    onSuccess('ok')
  }, 0)
}
const { Option } = Select
const { TextArea } = Input;

class TemplateForm extends Component {
  constructor(props) {
    super(props)
    this.state = {
      selectedUploadFileType: '',
      fileList: [],
      fileUrl: [{
        logo: '',
      }],
      selctedFieldValues: [],
    }
  }
  componentWillReceiveProps(nextProps) {
    const {
      UploadDataUrl,
      UploadDataUrlMessage
    } = nextProps
    if (UploadDataUrlMessage === 'success') {
      const { fileUrl, selectedUploadFileType } = this.state
      let obj = { ...fileUrl[0] }
      if (obj.hasOwnProperty(selectedUploadFileType)) {
        obj[selectedUploadFileType] = UploadDataUrl
        this.setState({
          fileUrl: [obj]
        })
      }
    }
  }

  componentDidMount() {
    const { getPartnerProductTemplate, selectedProduct } = this.props
    if (selectedProduct) {
      let productDataKey = _.get(getPartnerProductTemplate, 'products', []).filter(item => Object.keys(item)[0] === selectedProduct)[0]
      let productDataValue = productDataKey && Object.values(productDataKey)[0]
      this.fileUploadDataUpdate(productDataValue)
    } else {
      let partnerData = _.get(getPartnerProductTemplate, 'partner', [])
      this.fileUploadDataUpdate(partnerData)
    }
  }

  fileUploadDataUpdate = (searchItem) => {
    const { fileUrl } = this.state
    let newFileUploadArray = []
    let newFileUploadData = { ...fileUrl[0] }
    searchItem.forEach(item => {
      let imageKey = Object.keys(item)[0]
      if (imageKey in fileUrl[0]) {
        newFileUploadData[imageKey] = item[imageKey]
      }
    })
    newFileUploadArray.push(newFileUploadData)
    this.setState({
      fileUrl: newFileUploadArray
    })
  }

  async handleUpload(info, type) {
    if (info.file.status === 'done' || info.file.status === 'error') {
      const isGt20MB = info.file.size / 1024 / 1024 > 20
      if (isGt20MB) {
        message.error('File is to big, max 20mb')
        return
      }
      if (!isGt20MB) { // eslint-disable-line
        const file = info.file.originFileObj
        this.setState({
          selectedUploadFileType: type,
          filename: file.name,
          filesize: file.size,
          file,
          fileType: info.file.type
        })
        this.startUpload(file)
      } else {
        message.error('File is not supported')
      }
    }
  }
  async validateForm() {
    return new Promise(resolve => {
      this.props.form.validateFields((error) => {
        resolve(!error)
      })
    })
  }

  startUpload = (file) => {
    let formData = new FormData()
    formData.append('file', file)
    this.props.startUploadTemplate({ formData })
  }

  normFile = e => {
    if (Array.isArray(e)) {
      return e
    }
    return e && e.fileList
  };

  handleTemplateChanges = e => {
    e.preventDefault()
    const { form, partnerCode } = this.props
    const { fileUrl } = this.state
    const values = form.getFieldsValue()
    if (values['product']) {
      let attributes = []
      for (let i in fileUrl[0]) {
        let data = {}
        data['key'] = i
        data['value'] = fileUrl[0][i]
        data['is_active'] = values[`${i}_is_active`]
        attributes.push(data)
      }
      let additionalText = {
        'key': 'additionalText',
        'value': values['additionalText'],
        'is_active': values['input_is_active']
      }
      attributes.push(additionalText)
      let benefits = {
        'key': 'benefits',
        'value': values['benefits'],
        'is_active': values['input_is_active']
      }
      attributes.push(benefits)
      let endorsementUrl = {
        'key': 'endorsementUrl',
        'value': values['endorsementUrl'],
        'is_active': values['input_is_active']
      }
      attributes.push(endorsementUrl)
      let colorCode = {
        'key': 'colorCode',
        'value': values['colorCode'],
        'is_active': values['input_is_active']
      }
      attributes.push(colorCode)
      let theme = {
        'key': 'theme',
        'value': values['theme'],
        'is_active': values['input_is_active']
      }
      attributes.push(theme)
      let productPayload = {
        'partner': partnerCode,
        'data': {
          'product': values['product'],
          'attributes': attributes
        }
      }
      this.props.addNotificationTemplateProductRequest(productPayload)
      this.handleCancel()
    } else {
      let payload = {}
      for (let i in fileUrl[0]) {
        payload[i] = fileUrl[0][i]
      }

      let partnerPayload = {
        'partner': partnerCode,
        'data': {
          ...payload,
          'footerColor': values['footerColor']
        }
      }
      this.props.addNotificationTemplatePartnerRequest(partnerPayload)
      this.handleCancel()
    }
  }
  handleCancel = () => {
    this.props.form.resetFields()
    this.props.onCloseModal()
  }

  initialValueData = (data, type) => {
    // const {fileUrl} = this.state;
    let fileUrls = data && data.filter(item => Object.keys(item)[0] === type)[0]
    let fileList = []
    let imageUrl = fileUrls && Object.values(fileUrls)[0]
    if (imageUrl) {
      fileList.push(
        {
          uid: '-1',
          name: 'Default Images',
          status: 'done',
          url: imageUrl || '',
          thumbUrl: imageUrl || ''
        }
      )
    }
    return fileList
  }
  activeStateChecker = (data, type) => {
    if (data) {
      const objectFound = _.filter(data, (item) => Object.keys(item)[0] === type)[0] || {}
      if (Object.keys(objectFound).length) {
        return _.get(objectFound, 'is_active', false)
      }
    }
    return false
  }
  labelComponentRefactor = (labelName, productView, productValue, type, classname) => {
    let { getFieldDecorator } = this.props.form
    return (
      <div class='labelBlock'>
        {
          type === 'logo'
            ? <Form.Item>
              {getFieldDecorator(type, {
                //  rules: [{
                //   //  required:true,
                //   message: 'Field cannot be empty!'
                // }],
                valuePropName: 'fileList',
                initialValue: productValue ? this.initialValueData(productValue, type) : [],
                getValueFromEvent: this.normFile
              })(
                <Upload
                  name={type}
                  listType='picture'
                  multiple={false}
                  customRequest={dummyRequest}
                  onChange={file => this.handleUpload(file, type)}
                >
                  <Button>
                    <Icon type='upload' /> {labelName}
                  </Button>
                </Upload>
              )}
            </Form.Item>
            : <Form.Item style={{ width: '100%' }}>
              {getFieldDecorator(classname, {
                rules: [{
                  message: 'Field cannot be empty!'
                }],
                initialValue: _.get((productValue && productValue.filter(item => Object.keys(item)[0] === classname)[0]), classname, '')
              })(
                  type === 'area' ?
                    (<TextArea
                      placeholder={labelName}
                    />)
                    :
                    (<Input
                      placeholder={labelName}
                    />)
                  
              )}

            </Form.Item>
        }
        <div className='UploadCheckBox'>
          {
            productView &&
            <Form.Item>
              {
                getFieldDecorator(`${type}_is_active`, {
                  valuePropName: 'checked',
                  initialValue: this.activeStateChecker(productValue, type)
                })(
                  <Checkbox>Config Status</Checkbox>
                )
              }
            </Form.Item>
          }
        </div>
      </div>
    )
  }

  render() {
    const { form, products, getPartnerProductTemplate, selectedProduct } = this.props
    const initialProduct = _.get(getPartnerProductTemplate, 'products', [])
    const initialPartner = _.get(getPartnerProductTemplate, 'partner', [])
    let productObject = []
    let productValue
    if (initialProduct.length) {
      var productView = true
      productObject = _.filter(initialProduct, (item) => Object.keys(item)[0] === selectedProduct)[0] || {}
      productValue = Object.values(productObject)[0]
    } else if (initialPartner.length) {
      productValue = initialPartner
    }
    const { getFieldDecorator } = form
    return (
      <React.Fragment>
        {
          <Modal
            title='Template Builder Configuration'
            visible={this.props.isOpen}
            footer={null}
            closable={false}
            maskClosable={false}
          >
            <ModalWrapper>
              <Form onSubmit={this.handleTemplateChanges}>
                {
                  (products && products.length > 0) &&
                  <div className='FormItemComponent'>
                    <label>Select Product</label>
                    <div className='formItemClass'>
                      <Form.Item>
                        {getFieldDecorator('product', {
                          rules: [{
                            // required: true,
                            message: 'Please select Product!!'
                          }],
                          initialValue: this.props.selectedProduct || ''
                        })(
                          <Select placeholder='Please select a product' disabled={selectedProduct}>
                            {
                              (products && products.length) &&
                              products.map(item => <Option value={item.name}>{item.display_name}</Option>)
                            }
                          </Select>
                        )}
                      </Form.Item>
                    </div>
                  </div>
                }

                <Row type='flex' justify='space-between' className='fieldsRow'>
                  <label>Add addition text</label>
                  <Col span={24} className='rowStyle'>
                    {this.labelComponentRefactor('Add additional text', false, productValue, 'area', 'additionalText')}
                  </Col>
                  <label>Add Benefits</label>
                  <Col span={24} className='rowStyle'>
                    {this.labelComponentRefactor('Add Benefits', false, productValue, 'area', 'benefits')}
                  </Col>
                  <label>Endorsement URL</label>
                  <Col span={24} className='rowStyle'>
                    {this.labelComponentRefactor('Endorsement URL', false, productValue, 'input', 'endorsementUrl')}
                  </Col>
                  <>
                    <label>Theme</label>
                    <Col span={24} className='rowStyle'>
                      <Form.Item>
                        {getFieldDecorator('theme', {
                          rules: [{
                            // required: true,
                            message: 'Please select a Theme'
                          }],
                          initialValue: _.get((productValue && productValue.filter(item => Object.keys(item)[0] === 'theme')[0]), 'theme', '')
                        })(
                          <Select placeholder='Please select a Theme'>
                            <Option value='light'>Light</Option>
                            <Option value='dark'>Dark</Option>
                          </Select>
                        )}
                      </Form.Item>
                    </Col>
                    <label>Color Code</label>
                    <Col span={24} className='rowStyle'>
                      <Form.Item>
                        {getFieldDecorator('colorCode', {
                          rules: [{
                            // required: true,
                            message: 'Please select a Theme'
                          }],
                          initialValue: _.get((productValue && productValue.filter(item => Object.keys(item)[0] === 'colorCode')[0]), 'colorCode', '')
                        })(
                          <Input placeholder='Color Code' />
                        )}
                      </Form.Item>
                    </Col>
                  </>

                  <Col span={24} className='rowStyle'>
                    {this.labelComponentRefactor('Change Logo', productView, productValue, 'logo')}
                  </Col>
                </Row>

                <div style={{ textAlign: 'right' }}>
                  <Button key='back' onClick={this.handleCancel}>Cancel</Button>
                  <Button
                    key='submit'
                    type='primary'
                    htmlType='submit'
                    style={{ marginLeft: '10px' }}
                  >
                    Submit
                  </Button>
                </div>
              </Form>
            </ModalWrapper>
          </Modal>
        }
      </React.Fragment>
    )
  }
}
const WrapperForm = Form.create()(TemplateForm)
export default connect(state => ({
  UploadDataUrl: state.Notifications.templateUploadURl,
  uploadingImageLoading: state.Loading.UPLOAD_NOTIFICATIONS_TEMPLATE_ATTRIBUTE,
  UploadDataUrlMessage: state.Notifications.templateUploadURlMessage,
  getPartnerProductTemplate: state.Partner.getPartnerProductTemplateData
}), {
  startUploadTemplate,
  addNotificationTemplateProductRequest,
  addNotificationTemplatePartnerRequest
})(WrapperForm)
