import React, { PureComponent } from 'react'
import PropTypes from 'prop-types'
import { connect } from 'react-redux'
import {
  Modal,
  Button,
  Select,
  Form,
  Input,
  Upload,
  Icon,
  Spin,
  Alert,
  message
} from 'antd'
import partnerAction from '../../redux/partner/actions'
import NewPartnerStyled, { FormModalStyle } from './newPartner.style.js'
import loadingActions from '../../../redux/loading/actions'
import errorActions from '../../../redux/error/actions'
import validator from '../../../helpers/validator'
import {mapEnvWithDomain} from '../../../helpers/utility';
import { BASE_IMG_URL_S3 } from '../../../helpers/constant.js'

const Option = Select.Option

const FormItem = Form.Item
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions
const { postImageRequest, addWhiteLabelConfig, getPartnerDomainData, resetPartnerData } = partnerAction

class AddUserPannelConfig extends PureComponent {
  constructor (props) {
    super(props)
    this.state = {
      isVisible: false,
      value: '',
      config: [],
      loader: false,
      currentUploadingAttributeName: '',
      imageObj: {},
      product_name: ''
    }
    this.onChange = this.onChange.bind(this)
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      isOpen,
      partnerImage,
      postPartnerImageLoading,
      postPartnerImageError
    } = nextProps
    const { currentUploadingAttributeName, imageObj } = this.state
    this.setState({ isVisible: isOpen, partner: this.props.partner })

    if (postPartnerImageLoading === false && postPartnerImageError === false) {
      if (currentUploadingAttributeName !== '') {
        let obj
        if (Object.keys(this.state.imageObj).length > 0) {
          obj = {
            ...imageObj,
            [currentUploadingAttributeName]: partnerImage
          }
        } else {
          obj = {
            [currentUploadingAttributeName]: partnerImage
          }
        }
        this.setState({
          imageObj: {
            ...obj
          }
        }, () => {
          this.props.resetLoadingRedux(['POST_PARTNER_IMAGE'])
          this.props.resetErrorRedux(['POST_PARTNER_IMAGE'])
        })
      }
    }
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error, values) => {
        resolve(!error)
      })
    })
  }

  handleSubmit = async e => {
    e.preventDefault()
    const valid = await this.validateForm()
    if (valid) {
      this.setState({
        isVisible: false,
        imageObj: {}
      })
      const { form, partner } = this.props
      const data = form.getFieldsValue()
      const configPayload = Object.keys(data).map(key => ({
        config_type_name: key,
        value: data[key]
      })).filter(item => (item.config_type_name !== 'url' && item.config_type_name !== 'product'))

      const payload = {
        domain_configs: configPayload,
        url: data.url,
        product: data.product || null
      }
      this.props.addWhiteLabelConfig({ body: payload, params: { partner } })
    }
  }

  handleCancel = e => {
    this.props.form.resetFields()
    this.props.triggerClose()
  }

  validateNumber (event) {
    const key = window.event ? event.keyCode : event.which
    if (event.keyCode === 8 || event.keyCode === 46) {
      return true
    } else if (key < 48 || key > 57) {
      return false
    } else {
      return true
    }
  }

  onChange (e) {
    const re = /^[0-9\b]+$/
    if (e.target.value === '' || re.test(e.target.value)) {
      this.setState({ value: e.target.value })
    }
  }

  uploadImage (e, name) {
    const isLt10KB = e.file.size / 1024 / 1024 < 0.01
    const isGt20MB = e.file.size / 1024 / 1024 > 20

    if (isLt10KB) {
      message.error('Image is to small, min 10kb')
      return
    }
    if (isGt20MB) {
      message.error('Image is to big, max 20mb')
      return
    }
    if ((e.file.type === 'image/jpeg' || e.file.type === 'image/jpg' || e.file.type === 'image/png' && !isLt10KB && !isGt20MB)) { // eslint-disable-line
      const data = new FormData()
      data.append('file', e.file)
      this.setState({
        currentUploadingAttributeName: name
      })
      this.props.postImageRequest({ body: data })
    } else {
      message.error('File is not supported')
    }
  }

  getUrl = (name) => {
    const { imageObj } = this.state
    if (Object.prototype.hasOwnProperty.call(imageObj, name)) {
      return imageObj[name]
    }
    return ''
  }

  getFormField (value) {
    const {
      form,
      postPartnerImageLoading
    } = this.props
    const { getFieldDecorator } = form
    const {
      name,
      field_type: fieldType
    } = value
    let defaultColor
    let colorCheck
    switch (name) {
      case 'BRAND_COLOR':
        defaultColor='#ffffff'
        break;
      case 'SECONDARY_COLOR':
        defaultColor='#e11931'
        break;
      case 'FONT_COLOR':
        defaultColor='#000000'
        break;
      case 'HIGHLIGHTER_COLOR':
        defaultColor='#e11931'
        break;
      case 'FOOTER_COLOR':
        defaultColor='#000000'
        break;
      case 'FORM_COLOR':
        colorCheck = true
        defaultColor='#e11931'
        break;
      default:
        colorCheck = false
    }
    switch (fieldType) {
      case 'str':
        if (name === 'OTP_HEADER') {
          let defaultOTP= 'Masukkan no. telepon terdaftar'
          return (
            <div>
              <label className='custom-label'>{name.replace(/_/g, ' ').toLowerCase()}</label>
              <FormItem style={{ fontSize: '11px' }}>
                {getFieldDecorator(name, {
                  rules: [
                    {
                      required: true,
                      message: `${name.replace(/_/g, ' ').toLowerCase()} can not be empty`
                    },
                    { validator: colorCheck ? validator.colorChecker : '' }

                  ], initialValue:defaultOTP
                })(
                  <Input size='default' className='input-box' />
                )}
              </FormItem>
            </div>
          )
        }
        return (
          <div>
            <label className='custom-label'>{name.replace(/_/g, ' ').toLowerCase()}</label>
            <FormItem style={{ fontSize: '11px' }}>
              {getFieldDecorator(name, {
                rules: [
                  { required: true, message: `${name.replace(/_/g, ' ').toLowerCase()} can not be empty` },
                  { validator: colorCheck ? validator.colorChecker : '' }

                ], initialValue:defaultColor
              })(
                <Input size='default' className='input-box' />
              )}
            </FormItem>
          </div>
        )
      case 'url':
        let defaultLogo = `${BASE_IMG_URL_S3}/Logo_Pasarpolis.png`
        if (name.toLowerCase() === 'logo') {
          return (
            <div style={{ marginBottom: '24px' }} key={name}>
              <label className='custom-label'>{name.replace(/_/g, ' ').toLowerCase()}</label>
              <FormItem style={{ fontSize: '11px', marginBottom: '6px' }}>
                {getFieldDecorator(name, {
                  rules: [
                    { required: true, message: `${name.replace(/_/g, ' ').toLowerCase()} can not be empty` }
                  ],
                  initialValue: defaultLogo
                })(
                  <Input size='default' className='input-box' />
                )}
              </FormItem>
              <Upload
                customRequest={(e) => this.uploadImage(e, name)}
                showUploadList={false}
              >
                <Button
                  disabled={!!postPartnerImageLoading}
                >
                  <Spin spinning={(name === this.state.currentUploadingAttributeName) ? !!postPartnerImageLoading : false}>
                    <Icon type='upload' /> Click to Upload
                  </Spin>
                </Button>
              </Upload>
            </div>
          )
        }
        return (
          <div style={{ marginBottom: '24px' }} key={name}>
            <label className='custom-label'>{name.replace(/_/g, ' ').toLowerCase()}</label>
            <FormItem style={{ fontSize: '11px', marginBottom: '6px' }}>
              {getFieldDecorator(name, {
                rules: [
                  {
                    required: true,
                    message: `${name.replace(/_/g, ' ').toLowerCase()} can not be empty`
                  }
                ],
                initialValue: defaultLogo
              })(
                <Input size='default' className='input-box' />
              )}
            </FormItem>
            <Upload
              customRequest={(e) => this.uploadImage(e, name)}
              showUploadList={false}
            >
              <Button
                disabled={!!postPartnerImageLoading}
              >
                <Spin spinning={(name === this.state.currentUploadingAttributeName) ? !!postPartnerImageLoading : false}>
                  <Icon type='upload' /> Click to Upload
                </Spin>
              </Button>
            </Upload>
          </div>
        )
      case 'bool':
        return (
          <div>
            <label className='custom-label'>{name.replace(/_/g, ' ').toLowerCase()}</label>
            <FormItem style={{ fontSize: '11px' }}>
              {getFieldDecorator(name, {
                rules: [
                  { required: true, message: `Please select a value for ${name.replace(/_/g, ' ').toLowerCase()}` }
                ]
              })(
                <Select>
                  <Option value='0' key={0}>No</Option>
                  <Option value='1' key={1}>Yes</Option>
                </Select>
              )}
            </FormItem>
          </div>
        )
      default:
        return name
    }
  }

  render () {
    const { isVisible, loader } = this.state
    const { getFieldDecorator } = this.props.form
    const {
      defaultConfig,
      postPartnerImageLoading,
      postPartnerImageError,
      partnerImageStatus
    } = this.props
    //const initialUrl = 'policies-sandbox.pasarpolis.io'
    return (
      <Spin tip='Loading...' spinning={loader}>
        <NewPartnerStyled>
          <Modal
            closable={false}
            maskClosable={false}
            title='Add User Panel Config'
            visible={isVisible}
            footer={null}
            className='new-partner-modal'
          >
            {
              !postPartnerImageLoading && postPartnerImageError && (
                <Alert
                  message={partnerImageStatus || 'Error uploading image'}
                  type='error'
                  style={{ marginBottom: '10px' }}
                />
              )
            }
            <FormModalStyle>
              <Form onSubmit={this.handleSubmit}>
                <label className='custom-label'>Url</label>
                <Form.Item style={{ fontSize: '11px' }}>
                  {getFieldDecorator('url', {
                    rules: [{ required: true, message: 'Please enter url!' },
                    {
                      validator: (_, value) => value === mapEnvWithDomain('policies') || value === `https://${mapEnvWithDomain('policies')}` ? false : true,
                      message : "You cannot use this URL"
                    }
                ]
                  })(
                    <Input
                      placeholder='Enter the url'
                    />
                  )}
                </Form.Item>

                <label className='custom-label'>Product</label>
                <Form.Item style={{ fontSize: '11px' }}>
                  {getFieldDecorator('product', {
                    rules: [{
                      required: false,
                      message: 'Please enter product name!'
                    }]
                  })(
                    <Input
                      placeholder='Enter the Product Name'
                      onChange={(e) => { this.setState({ product_name: e.target.value }) }}
                    />
                  )}
                </Form.Item>
                {
                  defaultConfig.map(config => {
                    return this.getFormField(config)
                  })
                }
                <div style={{ textAlign: 'right' }}>
                  <Button key='back' onClick={this.handleCancel}>Cancel</Button>
                  <Button
                    key='submit'
                    type='primary'
                    htmlType='submit'
                    style={{ marginLeft: '10px' }}
                  >
                    Submit
                  </Button>
                </div>
              </Form>
            </FormModalStyle>
          </Modal>
        </NewPartnerStyled>
      </Spin>
    )
  }
}

AddUserPannelConfig.propTypes = {
  isOpen: PropTypes.bool,
  defaultConfig: PropTypes.array
}

AddUserPannelConfig.defaultProps = {
  isOpen: false,
  defaultConfig: []
}

const WrappedForm = Form.create({})(AddUserPannelConfig)

export default connect(
  state => ({
    partnerGroups: state.PartnerGroups,
    // statusAddNewPartnerConfig: state.Partner.statusAddNewPartnerConfig,
    // defaultConfig: state.Partner.defaultConfig,
    partnerData: state.Partner,
    // timezone: state.Partner.timezones,
    // addWhiteLabelConfigLoading: state.Loading.ADD_WHITELABLE_CONFIG,
    // addWhiteLabelConfigError: state.Error.ADD_WHITELABLE_CONFIG,
    partnerImage: state.Partner.partnerImage,
    partnerImageStatus: state.Partner.partnerImageStatus,
    postPartnerImageLoading: state.Loading.POST_PARTNER_IMAGE,
    postPartnerImageError: state.Error.POST_PARTNER_IMAGE

  }),
  {
    resetPartnerData,
    getPartnerDomainData,
    postImageRequest,
    addWhiteLabelConfig,
    resetLoadingRedux,
    resetErrorRedux
  }
)(WrappedForm)
