import React, { PureComponent } from 'react'
import PropTypes from 'prop-types'
import { connect } from 'react-redux'
import {
  Modal,
  Button,
  Select,
  Form,
  Input,
  notification,
  Upload,
  Icon,
  Spin,
  Alert,
  message
} from 'antd'
import partnerAction from '../../redux/partner/actions'
import NewPartnerStyled from './newPartner.style.js'
import validator from '../../../helpers/validator'

const Option = Select.Option

const FormItem = Form.Item
const { addPartnerConfig, resetState, postImageRequest } = partnerAction

class AddPartnerConfig extends PureComponent {
  constructor (props) {
    super(props)
    this.state = {
      isVisible: false,
      submitting: false,
      value: '',
      config: []
    }
    this.onChange = this.onChange.bind(this)
  }

  componentWillReceiveProps (nextProps) {
    const { isOpen, statusAddNewPartnerConfig } = nextProps
    if (nextProps.defaultConfig && nextProps.defaultConfig.length > 0) {
      this.setState({ config: nextProps.defaultConfig })
    }
    if (statusAddNewPartnerConfig !== '' && statusAddNewPartnerConfig === 'success') {
      notification['success']({
        message: 'success',
        description: ''
      })
      this.setState({ submitting: false })
      this.resetState()
      this.props.triggerClose()
      this.props.form.resetFields()
    }
    if (statusAddNewPartnerConfig !== '' && statusAddNewPartnerConfig !== 'success') {
      this.setState({ submitting: false })
      notification['error']({
        message: 'failed',
        description: statusAddNewPartnerConfig
      })
      this.resetState()
    }
    this.setState({ isVisible: isOpen, partner: this.props.partner })
  }
  resetState = () => {
    this.props.resetState()
  }
  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error, values) => {
        resolve(!error)
      })
    })
  }

  onSubmit = async e => {
    e.preventDefault()
    this.setState({ submitting: true })
    const valid = await this.validateForm()
    if (!valid) {
      this.setState({ submitting: false })
      return
    }
    const { form } = this.props
    const data = form.getFieldsValue()
    const configPayload = Object.keys(data).map(key => ({
      'config_type_name': key,
      'value': data[key]
    }))
    let configFilterData = configPayload.filter(item => item.config_type_name !== 'text')
    const payload = {
      'partner_configs': configFilterData,
      'partner_name': this.state.partner
    }

    this.props.addPartnerConfig({ payload })
  }

  handleCancel = e => {
    this.props.form.resetFields()
    this.props.triggerClose()
  }

  validateNumber (event) {
    var key = window.event ? event.keyCode : event.which
    if (event.keyCode === 8 || event.keyCode === 46) {
      return true
    } else if (key < 48 || key > 57) {
      return false
    } else {
      return true
    }
  }

  onChange (e) {
    const re = /^[0-9\b]+$/
    if (e.target.value === '' || re.test(e.target.value)) {
      this.setState({ value: e.target.value })
    }
  }

  uploadImage (e) {
    const isLt10KB = e.file.size / 1024 / 1024 < 0.01
    const isGt20MB = e.file.size / 1024 / 1024 > 20
    if (isLt10KB) {
      message.error('Image is to small, min 10kb')
      return
    }
    if (isGt20MB) {
      message.error('Image is to big, max 20mb')
      return
    }
    if ((e.file.type === 'image/jpeg' || e.file.type === 'image/jpg' || e.file.type === 'image/png' && !isLt10KB && !isGt20MB)) { // eslint-disable-line
      const data = new FormData()
      data.append('file', e.file)
      this.props.postImageRequest({ body: data })
    } else {
      message.error('File is not supported')
    }
  }

  getConfigValue = (identifier) => {
    if (this.state.config.length > 0) {
      let value = this.state.config.find(function (element) {
        // return the element if it satisfy the below conditon
        // else loop going on to find the next element
        return element.name === identifier
      })
      return value.default_value
    }
    return undefined
  }

  getFormField (value) {
    const {
      form,
      partnerImage,
      postPartnerImageLoading
    } = this.props
    const { getFieldDecorator } = form
    const {
      name,
      field_type: fieldType,
      default_value: defaultValue
    } = value
    let colorNameCheck
    switch (name) {
      case 'COLOR_CODE':
      case 'HEADER_TEXT_COLOR_CODE':
        colorNameCheck = true
        break
      default:
        colorNameCheck = false
    }
    switch (fieldType) {
      case 'str':
        return (
          <div>
            <label className='custom-label' style={{ textTransform: 'capitalize' }}>{name.replace(/_/g, ' ').toLowerCase()}</label>
            {
              name === 'TIMEZONE'
                ? <FormItem style={{ fontSize: '11px' }}>
                  {getFieldDecorator(name, {
                    rules: [
                      { required: true, message: `${name.replace(/_/g, ' ').toLowerCase()} can not be empty` }
                    ],
                    initialValue: this.getConfigValue(name)
                  })(
                    <Select
                      showSearch
                      placeholder='Select Timezone'
                      filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                      style={{ width: '100%' }}
                    >
                      {this.props.timezone.map(d => <Option value={d} key={d}>{d}</Option>)}
                    </Select>
                  )}
                </FormItem>
                : <FormItem style={{ fontSize: '11px' }}>
                  {getFieldDecorator(name, {
                    rules: [
                      { required: name !== 'PARTNER_DOMAIN', message: `${name.replace(/_/g, ' ').toLowerCase()} can not be empty` },
                      { validator: colorNameCheck ? validator.colorChecker : '' }

                    ],
                    initialValue: this.getConfigValue(name)
                  })(
                    <Input size='default' className='input-box' placeholder={defaultValue} />
                  )}
                </FormItem>
            }
          </div>
        )
      case 'url':
        return (
          <div style={{ marginBottom: '24px' }}>
            <label className='custom-label' style={{ textTransform: 'capitalize' }}>{name.replace(/_/g, ' ').toLowerCase()}</label>
            <FormItem style={{ fontSize: '11px', marginBottom: '6px' }}>
              {getFieldDecorator(name, {
                rules: [
                  { required: true, message: `${name.replace(/_/g, ' ').toLowerCase()} can not be empty` }
                ],
                initialValue: partnerImage || this.getConfigValue(name)
              })(
                <Input size='default' className='input-box' placeholder={defaultValue} />
              )}
            </FormItem>
            <Upload
              customRequest={(e) => this.uploadImage(e)}
              showUploadList={false}
            >
              <Button
                disabled={!!postPartnerImageLoading}
              >
                <Spin spinning={!!postPartnerImageLoading}>
                  <Icon type='upload' /> Click to Upload
                </Spin>
              </Button>
            </Upload>
          </div>
        )
      case 'bool':
        return (
          <div>
            <label className='custom-label' style={{ textTransform: 'capitalize' }}>{name.replace(/_/g, ' ').toLowerCase()}</label>
            <FormItem style={{ fontSize: '11px' }}>
              {getFieldDecorator(name, {
                rules: [
                  { required: true, message: `Please select a value for ${name.replace(/_/g, ' ').toLowerCase()}` }
                ],
                initialValue: this.getConfigValue(name)
              })(
                <Select>
                  <Option value='0' key={0}>No</Option>
                  <Option value='1' key={1}>Yes</Option>
                </Select>
              )}
            </FormItem>
          </div>
        )
      default:
        return name
    }
  }

  render () {
    const { isVisible, submitting } = this.state
    const {
      defaultConfig,
      postPartnerImageLoading,
      postPartnerImageError,
      partnerImageStatus
    } = this.props
    return (
      <NewPartnerStyled>
        <Modal
          closable={false}
          maskClosable={false}
          title={'Add partner config'}
          visible={isVisible}
          footer={null}
          className='new-partner-modal'
        >
          {
            !postPartnerImageLoading && postPartnerImageError && (
              <Alert
                message={partnerImageStatus || 'Error uploading image'}
                type='error'
                style={{ marginBottom: '10px' }}
              />
            )
          }
          <Form onSubmit={this.onSubmit}>
            {
              defaultConfig.map(config => {
                return this.getFormField(config)
              })
            }
            <div style={{ textAlign: 'right' }}>
              <Button key='back' onClick={this.handleCancel}>Cancel</Button>
              <Button
                key='submit'
                type='primary'
                htmlType='submit'
                loading={submitting}
                style={{ marginLeft: '10px' }}
              >
                Submit
              </Button>
            </div>
          </Form>
        </Modal>
      </NewPartnerStyled>
    )
  }
}

AddPartnerConfig.propTypes = {
  isOpen: PropTypes.bool,
  defaultConfig: PropTypes.array
}

AddPartnerConfig.defaultProps = {
  isOpen: false,
  defaultConfig: []
}

const WrappedForm = Form.create({})(AddPartnerConfig)

export default connect(
  state => ({
    partnerGroups: state.PartnerGroups,
    statusAddNewPartnerConfig: state.Partner.statusAddNewPartnerConfig,
    defaultConfig: state.Partner.defaultConfig,
    // partnerData: state.Partner,
    timezone: state.Partner.timezones,

    partnerImage: state.Partner.partnerImage,
    partnerImageStatus: state.Partner.partnerImageStatus,
    postPartnerImageLoading: state.Loading.POST_PARTNER_IMAGE,
    postPartnerImageError: state.Error.POST_PARTNER_IMAGE
  }),
  {
    addPartnerConfig,
    resetState,
    postImageRequest
  }
)(WrappedForm)
