import { useState } from 'react'
import { Modal, Form, Select, Button } from 'antd'
import AddClientModalWrapper from './AddClientModal.style'
const { Option } = Select

function AddClientModal ({ isOpen, clientList, onCloseModal, attachPartnerClient, partnerCode }) {
  const [selectedValue, setSelectedValue] = useState([])

  const onChange = (value) => {
    setSelectedValue(value)
  }

  const handleOk = () => {
    attachPartnerClient({
      query: {
        partner: partnerCode
      },
      body: {
        client_ids: selectedValue
      }
    })
  }

  return (
    <Modal
      title='Add Client'
      visible={isOpen}
      onCancel={onCloseModal}
      footer={null}
    >
      <AddClientModalWrapper>
        <div className='container'>
          Client Name :
          <Select
            showSearch
            mode='multiple'
            className='select'
            onChange={onChange}
            filterOption={(input, option) =>
              option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
          >
            {
              clientList?.map((client) => (
                <Option key={client?.id} value={client?.id}>{client?.name}</Option>
              ))
            }
          </Select>
        </div>
        <div className='btn-section'>
          <Button type='primary' disabled={selectedValue.length === 0} onClick={handleOk}>Corfirm</Button>
        </div>
      </AddClientModalWrapper>
    </Modal>
  )
}

export default Form.create({})(AddClientModal)
