import React from 'react'
import { Modal, Icon, Button } from 'antd'

class PartnerConfigMissing extends React.Component {
    createConfig = () => {
      this.props.createConfig()
    }
    render () {
      const { isOpen } = this.props
      return (
        <Modal
          closable={false}
          maskClosable={false}
          title=''
          visible={isOpen}
          footer={null}
        >
          <div style={{ textAlign: 'center' }}>
            <Icon
              type='smile'
              theme='twoTone'
              style={{ fontSize: '40px' }}
            /><br />
            <h2>
                        You need to create partner config before create user
            </h2>
            <Button type='primary' onClick={this.createConfig}>
                        Create Config
            </Button>
          </div>
        </Modal>
      )
    }
}

export default PartnerConfigMissing
