/* eslint-disable react-hooks/exhaustive-deps */
import React, { useState, useEffect } from 'react'
import { Row, Col, Card } from 'antd'
import { get } from 'lodash'
import AddProductModalComponent from './AddProductModal'
import CardWrapperStyleContainer, { P, CardWrapperContainer } from './CardWrapper.style'

export const TitleComponent = ({ data, id }) => {
  switch (data) {
    case 'add': {
      return (
        <span>Add new Product</span>
      )
    }
    case 'manual': {
      return (
        <span>{id}</span>
      )
    }
    case 'config': {
      return (
        <Row type='flex' justify='center'>
          <Col span={4}>
            <span>{id}</span>
          </Col>
          <Col span={20} style={{ textAlign: 'center' }}>
            <span className='title-tag-box'>product-config</span>
          </Col>
        </Row>
      )
    }
    default: return ''
  }
}

export const ExtraComponent = ({ delteHandler, data, permissions, toggleModal }) => {
  if (data !== 'add') {
    return (
      <Row type='flex'>
        <Col>
          <span className='anchor' onClick={() => toggleModal(true)}> Edit </span>
        </Col>
      </Row>
    )
  }
  return ''
}

export default function CardWrapperComponent (
  {
    className, id = '',
    type,
    title,
    item = {},
    permissions = [],
    partner,
    payload = [],
    submitHandler,
    delteHandler,
    goToLink,
    getPackages,
    packages = [],
    unsetstateFunction,
    modalLoader,
    isModalError,
    modalMessage,
    resetError,
    successMessage,
    history,
    generateApiSpecHandler
  }) {
  const [visible, toggleModal] = useState(false)
  const [payloadData, setPayload] = useState([])

  useEffect(() => {
    if (payload.length > 0 && payloadData.length === 0) {
      setPayload(payload)
    }
  }, [payload])

  const tableColumns = [
    {
      title: 'Package',
      dataIndex: 'code',
      key: 'code'
    },
    {
      title: 'Policy Creation',
      dataIndex: 'create_policy',
      key: 'create_policy',
      render: text => <span>{get(text, 'create_policy') ? 'Yes' : 'No'}</span>
    }
  ]
  const delteItem = () => {
    delteHandler(item)
  }

  const createPolicy = () => {
    const product = get(item, 'product')
    const partnerName = partner
    history.push({
      pathname: `/partner/test-create-policy/${partnerName}/${product}`
    })
  }
  useEffect(() => {
    if (successMessage === 'success') {
      if (typeof unsetstateFunction === 'function') {
        unsetstateFunction()
      }
      toggleModal(false)
    }
  }, [successMessage])
  return (
    <>
      {
        visible &&
          <AddProductModalComponent
            partner={partner}
            visible={visible}
            toggleModal={toggleModal}
            type={title}
            data={item}
            payload={payloadData}
            permissions={permissions}
            submitHandler={submitHandler}
            delteHandler={delteHandler}
            getPackages={getPackages}
            packages={packages}
            unsetstateFunction={unsetstateFunction}
            modalLoader={modalLoader}
            isModalError={isModalError}
            modalMessage={modalMessage}
            resetError={resetError}
          />
      }
      <CardWrapperContainer title={title}>
        <Card
          className={className}
          type={type}
          actions={(title !== 'add' && title !== 'manual') ? [<span className='card__buttons api_spec_color' key='create-policy' onClick={() => generateApiSpecHandler(item.product)}>Generate API Spec</span>, <span className='card__buttons' key='create-policy' onClick={createPolicy}>Create Policy</span>] : []}
          title={<TitleComponent data={title} id={id} />}
          extra={<ExtraComponent delteHandler={delteItem} data={title} permissions={permissions} toggleModal={toggleModal} />}
        >
          <CardWrapperStyleContainer>
            {
              title === 'add'
                ? (
                  <Row type='flex' justify='center'>
                    <Col>
                      <div onClick={() => toggleModal(true)}>
                        <i className='fas fa-plus fa-5x' />
                      </div>
                    </Col>
                  </Row>
                  )
                : (
                  <Row type='flex' justify='center'>
                    <Col span={24}>
                      <P type={title} onClick={() => item.creation_mode==="config"?goToLink(item.product):null}>{item.product}</P>
                    </Col>
                    <Col span={24}>
                      <table>
                        <tr>
                          {
                            tableColumns.map((item, index) => {
                              return (
                                <th className={index === 1 ? 'alignCenter' : 'alignLeft'} key={index}><b>{item.title}</b></th>
                              )
                            })
                          }
                        </tr>
                        {
                          item.packages.map((item, index) => {
                            return (
                              <tr key={index}>
                                <td className='alignLeft'>{item.code}</td>
                                <td className='alignCenter'>{item.create_policy ? 'Yes' : 'No'}</td>
                              </tr>
                            )
                          })
                        }
                      </table>
                    </Col>
                  </Row>
                  )
            }
          </CardWrapperStyleContainer>
        </Card>
      </CardWrapperContainer>
    </>
  )
}
