import React, { PureComponent } from 'react'
import PropTypes from 'prop-types'
import _ from 'lodash'
import { connect } from 'react-redux'
import { Modal, Spin, Select, Button, Form, Input, notification } from 'antd'

import partnerAction from '../../redux/partner/actions'
import loadingActions from '../../../redux/loading/actions'
import errorActions from '../../../redux/error/actions'

const FormItem = Form.Item
const Option = Select.Option
const { addUserGroup, updateUser, getPartnerDetails } = partnerAction
const { resetLoadingRedux } = loadingActions
const { resetErrorRedux } = errorActions

class AddUser extends PureComponent {
  constructor (props) {
    super(props)
    this.state = {
      isVisible: false,
      groups: [],
      loader: true,
      values: [],
      partnerCode: '',
      partnerId: '',
      submitting: false,
      messageAttachProduct: '',
      editUserData: props.editUserData
    }
  }

  componentDidMount () {
    this.props.resetErrorRedux(['UPDATE_USER'])
    this.props.resetLoadingRedux(['UPDATE_USER'])
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const { isOpen, partnerGroups, partnerCode, partnerId, updateUserLoading, updateUserError, updateUserMessage } = nextProps
    // const { partnerCode, partnerId } = this.state
    this.setState({ isVisible: isOpen, partnerCode, partnerId })
    if (partnerGroups) {
      if (partnerGroups.groupLists !== undefined && partnerGroups.groupLists.length > 0) {
        this.setState({ groups: partnerGroups.groupLists, loader: false })
      } else {
        this.setState({ groups: [], loader: false })
      }
    }
    if (updateUserLoading === false) {
      if (updateUserError === false) {
        this.props.onTriggerCloseAddUser()
        this.props.getPartnerDetails(partnerId)
        this.props.form.resetFields()
      }
      notification[updateUserError ? 'error' : 'success']({ message: updateUserMessage })
      this.props.resetErrorRedux(['UPDATE_USER'])
      this.props.resetLoadingRedux(['UPDATE_USER'])
    }
  }

  handleChange = value => {
    this.setState({ values: value })
  }

  handleIsInternalChange = value => {
    this.setState({
      is_internal_user: `${(value === 'yes')}`
    })
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error, values) => {
        resolve(!error)
      })
    })
  }

  onSubmit = async e => {
    e.preventDefault()
    this.setState({ submitting: true })
    const valid = await this.validateForm()
    if (!valid) {
      this.setState({ submitting: false })
      return
    }
    const { form, editUserData } = this.props
    const { partnerCode, partnerId } = this.state
    const data = form.getFieldsValue()
    this.setState({ submitting: false })

    if (editUserData) {
      data.user_id = _.get(editUserData, 'id')
      this.props.updateUser({
        body: {
          ...data
        },
        params: {
          partner: partnerCode
        }
      })
    } else {
      this.props.onTriggerCloseAddUser()
      this.props.onTriggerSubmit()
      this.props.addUserGroup({ data, partnerCode, partnerId })
      this.props.form.resetFields()
    }
  }

  handleCancel = e => {
    this.props.form.resetFields()
    this.props.onTriggerCloseAddUser()
  }

  render () {
    const { form, editUserData = {} } = this.props
    const { isVisible, groups, loader, values, submitting } = this.state
    const { getFieldDecorator } = form
    const { name, email, groups: userGroup, is_internal_user: isUserInternal } = editUserData
    const userGroups = userGroup && _.map(userGroup, 'name')

    return (
      <div>
        <Modal
          closable={false}
          maskClosable={false}
          title={email ? 'Edit User' : 'Add new user'}
          visible={isVisible}
          footer={null}
        >
          <Spin tip='Please wait ...' spinning={loader}>
            <Form onSubmit={this.onSubmit}>
              <label className='custom-label'>Name</label>
              <FormItem>
                {getFieldDecorator('name', {
                  rules: [
                    { required: true, message: 'Name can not be empty' }
                  ],
                  initialValue: name
                })(
                  <Input size='default' className='input-box' placeholder='Name' />
                )}
              </FormItem>
              <label className='custom-label'>Email</label>
              <FormItem>
                {getFieldDecorator('email', {
                  rules: [{
                    type: 'email', message: 'The input is not valid E-mail!'
                  }, {
                    required: true, message: 'Please input your E-mail!'
                  }],
                  initialValue: email
                })(
                  <Input
                    disabled={!!email}
                    className='input-box'
                    placeholder='Email'
                  />
                )}
              </FormItem>
              <label className='custom-label'>Group</label>
              <FormItem>
                {getFieldDecorator('groups', {
                  rules: [
                    { required: true, message: 'Group can not be empty' }
                  ],
                  initialValue: userGroups
                })(
                  <Select
                    mode='multiple'
                    placeholder='Select Group'
                    filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                    onSearch={this.fetchUser}
                    onChange={this.handleChange}
                    style={{ width: '100%' }}
                  >
                    { groups.map(d => <Option key={d} value={d}>{d}</Option>)}
                  </Select>
                )}
              </FormItem>
              <label className='custom-label'>Is Internal</label>
              <FormItem>
                {getFieldDecorator('is_internal_user', {
                  rules: [
                    { required: true, message: 'Please Select a Value' }
                  ],
                  setFieldsValue: values,
                  initialValue: isUserInternal
                })(
                  <Select
                    placeholder='Select Group'
                    disabled={!!email}
                    filterOption={(input, option) => option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                    onChange={this.handleIsInternalChange}
                    style={{ width: '100%' }}
                  >
                    <Option value>Yes</Option>
                    <Option value={false}>No</Option>
                  </Select>
                )}
              </FormItem>
              <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
                <Button key='back' onClick={this.handleCancel}>Cancel</Button>
                <Button
                  key='submit'
                  type='primary'
                  htmlType='submit'
                  loading={submitting}
                  style={{ marginLeft: '10px' }}
                >
                  Submit
                </Button>
              </div>
            </Form>
          </Spin>
        </Modal>
      </div>
    )
  }
}

AddUser.propTypes = {
  isOpen: PropTypes.bool,
  partnerData: PropTypes.object.isRequired
}

AddUser.defaultProps = {
  isOpen: false,
  partnerData: {}
}

const WrappedForm = Form.create({})(AddUser)

export default connect(
  state => ({
    partnerGroups: state.PartnerGroups,
    updateUserLoading: state.Loading.UPDATE_USER,
    updateUserError: state.Error.UPDATE_USER,
    updateUserMessage: state.Partner.updateUserMessage
  }),
  {
    addUserGroup,
    updateUser,
    getPartnerDetails,
    resetErrorRedux,
    resetLoadingRedux
  }
)(WrappedForm)
